"""Keeps only the new tables in an autogenerated migration (autogenerate also lists schema-qualified foreign keys and
platform tables it can't see the way they were made) and adds RLS for each of them.

    fmly\\Scripts\\python.exe scripts\\tidy_migration.py alembic\\versions\\0022_notifications.py table_a table_b ...

Writes the file back with: the create_table blocks and create_index lines of those tables, `enable_tenant_rls` for
each, and a downgrade that removes them.
"""

from __future__ import annotations

import sys
from pathlib import Path


def main() -> None:
    path, tables = Path(sys.argv[1]), sys.argv[2:]
    lines = path.read_text(encoding="utf-8").replace("\r\n", "\n").split("\n")
    up = next(i for i, line in enumerate(lines) if line.startswith("def upgrade"))
    down = next(i for i, line in enumerate(lines) if line.startswith("def downgrade"))
    head = [line for line in lines[:up] if "### commands" not in line]
    if not any("enable_tenant_rls" in line for line in head):
        at = next(i for i, line in enumerate(head) if line.startswith("from alembic import op"))
        head.insert(at + 1, "\nfrom app.core.db.rls import disable_tenant_rls, enable_tenant_rls")
    keep: list[str] = []
    inside = False
    for line in lines[up + 1:down]:
        stripped = line.strip()
        if any(stripped.startswith(f"op.create_table('{t}'") for t in tables):
            inside = True
        if inside or any(stripped.startswith(f"op.create_index('") and f"'{t}'," in stripped for t in tables):
            keep.append(line)
        if inside and stripped == ")":
            inside = False
    body = ["def upgrade() -> None:", *keep]
    for table in tables:
        body += [f'    for statement in enable_tenant_rls("{table}"):', "        op.execute(statement)"]
    body += ["", "", "def downgrade() -> None:"]
    for table in reversed(tables):
        body += [f'    for statement in disable_tenant_rls("{table}"):', "        op.execute(statement)",
                 f'    op.drop_table("{table}", schema="formaly")']
    path.write_text("\n".join(head + body) + "\n", encoding="utf-8")
    print(f"{path.name}: kept {len(keep)} lines for {', '.join(tables)}")


if __name__ == "__main__":
    main()
